local HostBuilder = require(script.Parent.Core.Hosting.HostBuilder)
local PlayerScopeService = require(script.Parent.Extensions.PlayerScope.PlayerScopeService)
local ServiceCollection = require(script.Parent.Core.DependencyInjection.ServiceCollection)
local PlayerLifeTimeService = require(script.Parent.Extensions.PlayerScope.PlayerLifeTimeService)

local module = {}

module.ConfigureServices = function(builder: ITangSengHostBuilder)
	-- 添加玩家作用域服务
	builder.Services:AddPlayerScopeService()

	-- 添加RobloxManifest
	builder.Services:AddSingleton("IRobloxManifest", function()
		return builder.RobloxManifest
	end)
end

module.RequireServices = function(host: IHost) end

return module
